+
+/* =========================
+   GALLERY PRO LUXE
+========================= */
+
+.gallery-section {
+  padding: 120px 20px;
+  background: linear-gradient(180deg, #0A0A0A, #1A1714);
+  overflow-x: hidden;
+}
+
+/* HEADER */
+.gallery-header {
+  text-align: center;
+  margin-bottom: 50px;
+}
+
+.gallery-header h2 {
+  font-family: 'Cormorant Garamond', serif;
+  font-size: clamp(32px, 5vw, 60px);
+  color: #FAF6EF;
+}
+
+.gallery-header p {
+  color: #8A7968;
+  font-size: 14px;
+  max-width: 400px;
+  margin: 10px auto;
+}
+
+/* FILTERS */
+.gallery-filters {
+  display: flex;
+  justify-content: center;
+  flex-wrap: wrap;
+  gap: 10px;
+  margin-bottom: 40px;
+}
+
+.gallery-filters button {
+  padding: 8px 18px;
+  border: 1px solid rgba(201,168,76,0.3);
+  background: transparent;
+  color: #8A7968;
+  font-size: 11px;
+  letter-spacing: 0.15em;
+  text-transform: uppercase;
+  cursor: pointer;
+  transition: 0.3s;
+}
+
+.gallery-filters button.active {
+  background: linear-gradient(135deg, #C9A84C, #E8C97A);
+  color: #0A0A0A;
+}
+
+/* GRID RESPONSIVE */
+.gallery-grid {
+  column-count: 3;
+  column-gap: 16px;
+  max-width: 1200px;
+  margin: 0 auto;
+}
+
+/* TABLET */
+@media (max-width: 1024px) {
+  .gallery-grid {
+    column-count: 2;
+  }
+}
+
+/* MOBILE */
+@media (max-width: 768px) {
+  .gallery-section {
+    padding: 80px 15px;
+  }
+
+  .gallery-grid {
+    column-count: 1;
+  }
+}
+
+/* ITEM */
+.gallery-item {
+  break-inside: avoid;
+  margin-bottom: 16px;
+  position: relative;
+  cursor: pointer;
+  border-radius: 6px;
+  overflow: hidden;
+}
+
+.gallery-item img {
+  width: 100%;
+  display: block;
+  transition: transform 0.4s;
+}
+
+.gallery-item:hover img {
+  transform: scale(1.05);
+}
+
+/* OVERLAY */
+.overlay {
+  position: absolute;
+  inset: 0;
+  background: linear-gradient(to top, rgba(0,0,0,0.9), transparent);
+  display: flex;
+  flex-direction: column;
+  justify-content: flex-end;
+  padding: 15px;
+  color: #FAF6EF;
+}
+
+.overlay span {
+  font-size: 10px;
+  color: #C9A84C;
+  letter-spacing: 0.2em;
+}
+
+/* LIGHTBOX */
+.lightbox {
+  position: fixed;
+  inset: 0;
+  background: rgba(0,0,0,0.92);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  z-index: 999;
+  padding: 20px;
+}
+
+.lightbox-content {
+  position: relative;
+  max-width: 90%;
+  max-height: 90%;
+  text-align: center;
+}
+
+.lightbox-content img {
+  max-width: 100%;
+  max-height: 70vh;
+  border-radius: 6px;
+}
+
+.lightbox-content h3 {
+  color: #FAF6EF;
+  margin-top: 10px;
+}
+
+.lightbox-content p {
+  color: #C9A84C;
+  font-size: 12px;
+  letter-spacing: 0.2em;
+}
+
+.close {
+  position: absolute;
+  top: -15px;
+  right: -15px;
+  width: 35px;
+  height: 35px;
+  border-radius: 50%;
+  background: #C9A84C;
+  color: #0A0A0A;
+  border: none;
+  font-size: 20px;
+  cursor: pointer;
 }
