+}
+
+.ig-lightbox-content {
+  max-width: 90%;
+  text-align: center;
+  color: white;
+}
+
+.ig-lightbox-content img {
+  max-height: 70vh;
+  width: 100%;
+  object-fit: contain;
+}
+
+/* =========================
+   RESPONSIVE SWITCH
+========================= */
+
+@media (max-width: 768px) {
+  .ig-grid {
+    display: none;
+  }
+
+  .ig-swipe {
+    display: block;
+  }
