@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,300;0,400;0,500;0,600;1,300;1,400&family=Jost:wght@300;400;500;600&display=swap');

/* =========================
   RESET GLOBAL
========================= */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* IMPORTANT FIX MOBILE */
* {
  min-width: 0;
}

/* =========================
   VARIABLES
========================= */
:root {
  --gold: #C9A84C;
  --gold-light: #E8C97A;
  --gold-dark: #8B6914;

  --black: #0A0A0A;
  --charcoal: #1A1714;
  --warm-dark: #2A2118;

  --cream: #FAF6EF;
  --blush: #F2E8E0;
  --rose: #D4956A;

  --text-light: #8A7968;
  --white: #FFFFFF;

  --font-display: 'Cormorant Garamond', serif;
  --font-body: 'Jost', sans-serif;

  --radius-sm: 4px;
  --radius-md: 12px;
  --radius-lg: 24px;
  --radius-full: 9999px;

  --shadow-gold: 0 4px 30px rgba(201, 168, 76, 0.2);
  --shadow-dark: 0 8px 40px rgba(0,0,0,0.4);
}

/* =========================
   BASE HTML / BODY
========================= */
html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-body);
  background: var(--black);
  color: var(--cream);
  line-height: 1.6;

  -webkit-font-smoothing: antialiased;

  /* FIX SCROLL MOBILE */
  overflow-x: hidden;
  width: 100%;
  max-width: 100%;
}

/* =========================
   TITRES
========================= */
h1, h2, h3, h4 {
  font-family: var(--font-display);
  font-weight: 400;
  line-height: 1.15;
}

/* =========================
   ELEMENTS
========================= */
button {
  cursor: pointer;
  border: none;
  outline: none;
  font-family: var(--font-body);
}

input, select, textarea {
  font-family: var(--font-body);
}

a {
  text-decoration: none;
  color: inherit;
}

/* Images responsives */
img {
  max-width: 100%;
  height: auto;
  display: block;
}

/* =========================
   CONTENEUR GLOBAL (IMPORTANT)
========================= */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 16px;
}

/* =========================
   SCROLLBAR LUXE
========================= */
::-webkit-scrollbar {
  width: 5px;
}

::-webkit-scrollbar-track {
  background: var(--charcoal);
}

::-webkit-scrollbar-thumb {
  background: var(--gold-dark);
  border-radius: 10px;
}

/* =========================
   ANIMATIONS
========================= */
@keyframes shimmer {
  0% { background-position: -200% center; }
  100% { background-position: 200% center; }
}

@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(30px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes pulse-gold {
  0%, 100% { box-shadow: 0 0 0 0 rgba(201, 168, 76, 0.4); }
  50% { box-shadow: 0 0 0 10px rgba(201, 168, 76, 0); }
}

.fade-in-up {
  animation: fadeInUp 0.7s ease forwards;
}

/* =========================
   RESPONSIVE FIX GLOBAL
========================= */

/* évite débordement flex */
.flex, .grid {
  min-width: 0;
}

/* images / media safe */
img, video, iframe {
  max-width: 100%;
  height: auto;
}

/* =========================
   MOBILE OPTIMIZATION
========================= */
@media (max-width: 768px) {
  body {
    font-size: 14px;
  }

  h1 {
    font-size: 24px;
  }

  h2 {
    font-size: 20px;
  }
}
